const path = require('node:path');

const {
  budgetApplies,
  extractDurableSlice,
  resolveGoalBudget,
  splitFrontmatter,
  LOG_ANCHOR
} = require(path.resolve(__dirname, '../../../../../.skilled/hooks/goal/lib/goal-slice.cjs'));
const { exitIfValidationOff } = require(path.join(__dirname, '..', '..', 'shared', 'scripts', 'validation-switch.cjs'));

