TMP=$(mktemp -d); awk -v out="$TMP" '
/^```bash$/ {inb=1; n++; next}
/^```$/ && inb {inb=0; next}
inb {print > (out "/block" n ".sh")}
' specs/system-speckit/054-weak-model-spec-authoring/008-playbook-run-in-worktree/tasks.md
fail=0
for f in "$TMP"/block*.sh; do
  if ! bash -n "$f" 2>"$f.err"; then echo "SYNTAX FAIL $f"; cat "$f.err"; fail=1; fi
done
echo "blocks=$(ls "$TMP"/block*.sh | wc -l | tr -d ' ') fail=$fail"

