printf 'F01\tP0 file.txt:1 | bad | fix\nF02\tP1 other.md:2 | worse | fix2\n' > "$TMP/findings.tsv"
printf 'T018-APPLIED F01\n| T018-RECORDED F02 | not ours |\n' > "$TMP/goal.md"
awk -F'\t' 'FILENAME == ARGV[1] { need[$1] = 1; next }
  /T018-(APPLIED|RECORDED) / {
    if (match($0, /T018-(APPLIED|RECORDED) F[0-9]+/)) {
      token = substr($0, RSTART, RLENGTH)
      split(token, parts, " ")
      done[parts[2]] = 1
    }
  }
  END { n = 0; u = 0; for (id in need) { n++; if (!(id in done)) u++ } printf "findings=%d\nunrecorded=%d\n", n, u }' "$TMP/findings.tsv" "$TMP/goal.md"
printf 'F03\tP1 third.md:3 | x | y\n' >> "$TMP/findings.tsv"
awk -F'\t' 'FILENAME == ARGV[1] { need[$1] = 1; next }
  /T018-(APPLIED|RECORDED) / {
    if (match($0, /T018-(APPLIED|RECORDED) F[0-9]+/)) {
      token = substr($0, RSTART, RLENGTH)
      split(token, parts, " ")
      done[parts[2]] = 1
    }
  }
  END { n = 0; u = 0; for (id in need) { n++; if (!(id in done)) u++ } printf "findings=%d\nunrecorded=%d\n", n, u }' "$TMP/findings.tsv" "$TMP/goal.md"

